const evento = $json;

const resumoOsv = String(evento.contexto_osv?.resumo ||
  'OSV: resultado ainda não disponível para esta análise. Isso não indica ausência de vulnerabilidades.').slice(0, 1000);

const contexto = {
  installation_id: evento.meta?.tenant_id,
  repositorio: evento.repositorio?.full_name,
  numero_pr: evento.pr?.numero,
  id_evento: evento.meta?.id_evento,
  task_run_id: evento.meta?.execution_id,
  osv_resumo: resumoOsv,
};

const autor = evento.pr?.autor?.login;
const motivo = evento.risco?.motivo || evento.risco?.explicacao;

if (
  evento.evento?.tipo !== 'aguardando_aprovacao' ||
  !Number.isSafeInteger(contexto.installation_id) ||
  contexto.installation_id <= 0 ||
  !contexto.repositorio ||
  !Number.isSafeInteger(contexto.numero_pr) ||
  contexto.numero_pr <= 0 ||
  !contexto.id_evento ||
  !contexto.task_run_id ||
  !autor ||
  !motivo
) {
  throw new Error('Evento de aprovação incompleto ou incompatível.');
}

const valorBotao = JSON.stringify(contexto);

if (valorBotao.length > 2000) {
  throw new Error('Contexto dos botões excede o limite do Slack.');
}
const urlPr = `https://github.com/${contexto.repositorio}/pull/${contexto.numero_pr}`;
const urlInformada = evento.recibo?.url;
const recibo = typeof urlInformada === 'string' && urlInformada.length <= 1900
  ? /^(https?:\/\/[^/?#@\s\\]+(?:\/[^/?#@\s\\]+)*)\/receipts\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})(?:\/verify)?\/?$/i.exec(urlInformada)
  : null;
const urlRecibo = recibo ? `${recibo[1]}/receipts/${recibo[2]}` : null;
const navegacao = [{
  type: 'button',
  text: { type: 'plain_text', text: 'Abrir PR' },
  action_id: 'abrir_pr',
  url: urlPr,
}];
if (urlRecibo) {
  navegacao.push(
    {
      type: 'button',
      text: { type: 'plain_text', text: 'Ver recibo' },
      action_id: 'abrir_recibo',
      url: urlRecibo,
    },
    {
      type: 'button',
      text: { type: 'plain_text', text: 'Verificar recibo' },
      action_id: 'verificar_recibo',
      url: urlRecibo + '/verify',
    },
  );
}
const verificacao = evento.verificacao_recibo;
const motivosFalha = { hash: 'hash divergente', chave_desconhecida: 'chave não reconhecida',
  assinatura: 'assinatura reprovada', conteudo: 'conteúdo reprovado', elo: 'elo da cadeia reprovado' };
const verificacaoConfirmada = verificacao?.correlacao_confirmada === true && verificacao?.fonte === 'nucleo';
const mensagemRecibo = !urlRecibo ? 'Recibo indisponível neste alerta.' :
  verificacaoConfirmada && verificacao.status === 'valido'
    ? 'Recibo: válido na verificação do núcleo e vinculado a esta análise.'
    : verificacaoConfirmada && verificacao.status === 'invalido' && Object.prototype.hasOwnProperty.call(motivosFalha, verificacao.falha)
      ? 'Recibo: inválido na verificação do núcleo — ' + motivosFalha[verificacao.falha] + '.'
      : 'Recibo: verificação indisponível para esta análise.';
const slack_payload = {
  text: `Aprovação pendente: ${contexto.repositorio} #${contexto.numero_pr}\n${urlPr}\n${resumoOsv}\n${mensagemRecibo}` +
    (urlRecibo ? `\nRecibo: ${urlRecibo}\nVerificação: ${urlRecibo}/verify` : ''),
  blocks: [
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text:
          `PR aguardando aprovação\n` +
          `${contexto.repositorio} #${contexto.numero_pr}\n` +
          `Autor: ${autor}`,
      },
    },
    {
       type: 'section',
      text: {
        type: 'plain_text',
        text: `Motivo do risco:\n${String(motivo).slice(0, 2800)}`,
      },
    },
    {
      type: 'section',
      block_id: 'aprova_contexto_osv',
      text: { type: 'plain_text', text: 'Contexto OSV para a decisão:\n' + resumoOsv },
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Aprovar' },
          style: 'primary',
          action_id: 'aprovar',
          value: valorBotao,
        },
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Pedir revisão' },
          action_id: 'solicitar_alteracao',
          value: valorBotao,
        },
      ],
    },
    {
      type: 'section',
      block_id: 'aprova_recibo_verificacao',
      text: { type: 'plain_text', text: mensagemRecibo },
    },
    { type: 'actions', elements: navegacao },
  ],
  unfurl_links: false,
  unfurl_media: false,
};
return {
  json: {
    ...evento,
    slack_payload,
  },
};

